package com.example.storytv;
import android.graphics.*;
final class FinishScreen {
 static void draw(Canvas c,Paint p,boolean tamil){c.drawColor(0xfffffaf1);float t=StoryMotion.phase();for(int i=0;i<12;i++){float angle=(float)(i*Math.PI/6+t*.15);float radius=150+(float)Math.sin(t*2+i)*12;StoryMotion.sparkle(c,p,640+(float)Math.cos(angle)*radius,210+(float)Math.sin(angle)*radius,7+(float)Math.abs(Math.sin(t+i))*6,i%2==0?0xffffc85c:0xff8ccac4);}p.setColor(0xffffe0a7);c.drawCircle(640,210,85+(float)Math.sin(t*2)*5,p);p.setTypeface(Typeface.create("sans-serif-medium",0));p.setTextAlign(Paint.Align.CENTER);p.setColor(0xffb57d2c);p.setTextSize(95);c.drawText("★",640,242,p);p.setColor(0xff20464c);p.setTextSize(48);c.drawText(tamil?"அருமையாக படித்தாய்!":"Wonderful reading!",640,370,p);p.setTextSize(26);p.setColor(0xff638082);c.drawText(tamil?"ஒரு கதையை முடித்துவிட்டாய்!":"You finished a story. Great job!",640,420,p);p.setColor(0xff315f67);c.drawRoundRect(465,470,815,554,22,22,p);p.setColor(Color.WHITE);p.setTextSize(28);c.drawText(tamil?"கதைகளுக்குச் செல்":"Back to stories",640,523,p);p.setColor(0xff668079);p.setTextSize(20);c.drawText("OK / BACK  Stories",640,625,p);p.setTextAlign(Paint.Align.LEFT);}
}
